files.content:
* { box-sizing: border-box; }
[hidden] { display: none !important; }

:root {
  color-scheme: light;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 16px;
  color: #202b3b;
  background: #e8f0ed;
}

body {
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: #e8f0ed;
  background-image: linear-gradient(rgba(40, 77, 69, .055) 1px, transparent 1px), linear-gradient(90deg, rgba(40, 77, 69, .055) 1px, transparent 1px);
  background-size: 24px 24px;
}

.calculator {
  width: min(100%, 440px);
  padding: 32px;
  border: 3px solid #202b3b;
  border-radius: 12px;
  background: #fbfaf4;
  box-shadow: 8px 8px 0 #202b3b;
}

.heading { margin-bottom: 28px; }
.eyebrow { margin: 0 0 8px; color: #36776c; font-size: .8rem; font-weight: 800; letter-spacing: .12em; }
h1 { margin: 0; font-size: clamp(2rem, 8vw, 2.7rem); line-height: 1.1; letter-spacing: -.06em; }
.subtitle { margin: 10px 0 0; color: #596575; }

.stack-panel { padding: 18px; border: 2px solid #202b3b; border-radius: 8px; background: #e5f0e9; }
.panel-heading { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
h2 { margin: 0; font-size: 1.05rem; }
.stack-count { color: #596575; font-size: .875rem; }
.stack { min-height: 104px; max-height: 220px; overflow-y: auto; display: flex; flex-direction: column-reverse; gap: 8px; margin: 14px 0 0; padding: 0; list-style: none; }
.stack li { display: flex; justify-content: space-between; align-items: center; padding: 10px 12px; border: 1px solid #9bb6a9; border-radius: 5px; background: #fbfaf4; font-weight: 700; }
.stack li small { color: #68756f; font-size: .75rem; font-weight: 500; }
.stack .empty { min-height: 72px; justify-content: center; border-style: dashed; color: #68756f; font-weight: 500; }

.message { min-height: 24px; margin: 16px 0; color: #36776c; font-size: .9rem; font-weight: 700; }
.message.error { color: #a33d37; }
.number-form label { display: block; margin-bottom: 8px; font-weight: 700; }
.input-row { display: flex; gap: 10px; }
input { min-width: 0; flex: 1; padding: 12px; border: 2px solid #9aa6a1; border-radius: 6px; background: #fff; color: #202b3b; font: inherit; }
input::placeholder { color: #89928f; }
.operations { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-top: 14px; }
.button { min-height: 48px; border: 2px solid #202b3b; border-radius: 6px; color: #202b3b; font: inherit; font-weight: 800; cursor: pointer; transition: transform .08s ease, box-shadow .08s ease, background-color .12s ease; }
.button:hover { transform: translateY(-2px); box-shadow: 0 3px 0 #202b3b; }
.button:active { transform: translateY(2px); box-shadow: none; }
.button:focus-visible, input:focus-visible { outline: 3px solid #d18b38; outline-offset: 3px; }
.button-primary { padding: 0 18px; background: #d6a14d; }
.button-operation { background: #fff; font-size: 1.4rem; }
.button-operation:hover { background: #f2dfbd; }
.button-clear { width: 100%; margin-top: 12px; background: #f3e5dd; }
.button-clear:hover { background: #e8c8b8; }
.hint { margin: 18px 0 0; color: #596575; font-size: .8rem; line-height: 1.6; }
kbd { padding: 2px 5px; border: 1px solid #b8c0bb; border-radius: 3px; background: #fff; color: #202b3b; font: inherit; }

@media (max-width: 420px) {
  body { padding: 20px 12px; }
  .calculator { padding: 22px 18px; box-shadow: 5px 5px 0 #202b3b; }
  .stack-panel { padding: 14px; }
}

const stack = [];
const stackElement = document.querySelector('#stack');
const countElement = document.querySelector('#stack-count');
const messageElement = document.querySelector('#message');
const numberInput = document.querySelector('#number-input');

function showMessage(text, isError = false) {
  messageElement.textContent = text;
  messageElement.classList.toggle('error', isError);
}

function renderStack() {
  stackElement.replaceChildren();
  countElement.textContent = `${stack.length} ${stack.length === 1 ? 'value' : 'values'}`;

  if (stack.length === 0) {
    const empty = document.createElement('li');
    empty.className = 'empty';
    empty.textContent = 'Your stack is empty';
    stackElement.append(empty);
    return;
  }

  stack.forEach((value, index) => {
    const item = document.createElement('li');
    const number = document.createElement('span');
    const position = document.createElement('small');
    number.textContent = formatNumber(value);
    position.textContent = index === stack.length - 1 ? 'top' : `#${index + 1}`;
    item.append(number, position);
    stackElement.append(item);
  });
}

function formatNumber(value) {
  return Number.isInteger(value) ? String(value) : String(Number(value.toPrecision(10)));
}

function pushNumber(value) {
  if (!Number.isFinite(value)) {
    showMessage('Enter a valid finite number.', true);
    return;
  }
  stack.push(value);
  renderStack();
  showMessage(`${formatNumber(value)} pushed.`);
}

function operate(operator) {
  if (stack.length < 2) {
    showMessage('Two values are needed for an operation.', true);
    return;
  }

  const right = stack.pop();
  const left = stack.pop();
  const result = operator === '+' ? left + right
    : operator === '-' ? left - right
    : operator === '*' ? left * right
    : left / right;

  if (!Number.isFinite(result)) {
    stack.push(left, right);
    renderStack();
    showMessage(operator === '/' && right === 0 ? 'Cannot divide by zero.' : 'Result is outside the supported range.', true);
    return;
  }

  stack.push(result);
  renderStack();
  showMessage(`${formatNumber(left)} ${operator} ${formatNumber(right)} = ${formatNumber(result)}`);
}

document.querySelector('#number-form').addEventListener('submit', (event) => {
  event.preventDefault();
  if (numberInput.value.trim() === '') {
    showMessage('Enter a number first.', true);
    numberInput.focus();
    return;
  }
  pushNumber(Number(numberInput.value));
  if (!messageElement.classList.contains('error')) numberInput.value = '';
});

document.querySelectorAll('[data-operation]').forEach((button) => {
  button.addEventListener('click', () => operate(button.dataset.operation));
});

document.querySelector('#clear-button').addEventListener('click', () => {
  stack.length = 0;
  renderStack();
  showMessage('Stack cleared.');
  numberInput.focus();
});

document.addEventListener('keydown', (event) => {
  if (event.altKey || event.ctrlKey || event.metaKey) return;
  const target = event.target;
  if (target instanceof HTMLInputElement) {
    if (event.key === 'Enter') return;
    if (/^[+*/-]$/.test(event.key)) {
      event.preventDefault();
      operate(event.key);
    }
    return;
  }
  if (/^[+*/-]$/.test(event.key)) {
    event.preventDefault();
    operate(event.key);
  } else if (event.key.toLowerCase() === 'c') {
    stack.length = 0;
    renderStack();
    showMessage('Stack cleared.');
  }
});

renderStack();
